const tabId = 1148881640;

const extracted = await browserjs(tabId, () => {
  // Let's find the search results container
  // Typically BBB results are under a main container with cards
  // Let's look for cards that contain an h3 with a link
  const headings = Array.from(document.querySelectorAll('h3 a'));
  const results = [];

  for (const a of headings) {
    const card = a.closest('.stack') || a.closest('div[class*="result"]') || a.closest('div[class*="card"]') || a.closest('div');
    if (!card) continue;

    // Check if it's an actual business listing (not filter, not ad header, etc.)
    const name = a.textContent.trim().replace(/^advertisement:\s*/i, '');
    const isAd = a.textContent.toLowerCase().includes('advertisement') || card.innerText.includes('Ad\nWhy are there ads');

    // Let's find rating, phone, address, categories
    const text = card.innerText;

    // Rating
    const ratingMatch = text.match(/BBB Rating:\s*([A-F][+-]?|NR)/i);
    const rating = ratingMatch ? ratingMatch[1] : null;

    // Phone
    const phoneMatch = text.match(/\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}/);
    const phone = phoneMatch ? phoneMatch[0] : null;

    // Accredited
    const isAccredited = text.includes('BBB Accredited') || card.querySelector('img[alt*="Accredited"]') !== null;

    // Address
    // Usually address is in a paragraph or contains city/state/zip
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

    results.push({
      name,
      url: a.href,
      isAd,
      rating,
      phone,
      isAccredited,
      cardText: text
    });
  }

  return results;
});

