const tabId = 1148881640;

const businesses = await browserjs(tabId, () => {
  const profileLinks = Array.from(document.querySelectorAll('a')).filter(a => a.href && a.href.includes('/profile/'));
  const list = [];
  const seen = new Set();

  for (const a of profileLinks) {
    const h3 = a.closest('h3');
    if (!h3) continue;

    const name = h3.textContent.trim().replace(/^advertisement:\s*/i, '');
    let cleanUrl = a.href;
    if (cleanUrl.includes('adurl=')) {
      cleanUrl = decodeURIComponent(cleanUrl.split('adurl=')[1]);
    }

    // Find the enclosing card by walking up until we find a container that encapsulates this listing
    let el = h3;
    while (el && el.parentElement && el.parentElement.tagName !== 'MAIN' && el.parentElement.querySelectorAll('h3').length === 1) {
      el = el.parentElement;
    }

    const cardText = el ? el.innerText : h3.innerText;

    // Key details extraction
    const ratingMatch = cardText.match(/BBB Rating:\s*([A-F][+-]?|NR)/i);
    const phoneMatch = cardText.match(/\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}/);
    const isAccredited = cardText.includes('BBB Accredited') || (el && !!el.querySelector('img[alt*="Accredited"]'));
    const isAd = h3.textContent.toLowerCase().includes('advertisement') || cardText.includes('Why are there ads');

    // Extract address: lines looking like street address or city, state zip
    const lines = cardText.split('\n').map(l => l.trim()).filter(Boolean);
    let address = null;
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      // Check for NY / NJ zip pattern
      if (/\b(NY|NJ)\s+\d{5}(-\d{4})?\b/.test(line)) {
        // May be preceded by street address line
        if (i > 0 && !lines[i-1].includes('BBB') && !lines[i-1].includes('Quote') && !lines[i-1].includes('Rating') && !lines[i-1].includes('(') && !lines[i-1].includes('Contractor')) {
          address = lines[i-1] + ', ' + line;
        } else {
          address = line;
        }
        break;
      }
    }

    // Categories
    let categories = [];
    for (const line of lines) {
      if (line.includes('Contractor') || line.includes('Roofing') || line.includes('Improvement') || line.includes('Services')) {
        if (!line.includes('advertisement') && !line.includes('Showing') && !line.includes('Department of Consumer') && !line.includes('BBB')) {
          categories.push(line);
        }
      }
    }

    if (!seen.has(name + (isAd ? '-ad' : ''))) {
      seen.add(name + (isAd ? '-ad' : ''));
      list.push({
        name,
        isAd,
        rating: ratingMatch ? ratingMatch[1] : 'N/A',
        isAccredited,
        phone: phoneMatch ? phoneMatch[0] : 'N/A',
        address: address || 'N/A',
        categories: categories.join('; '),
        url: cleanUrl
      });
    }
  }

  return list;
});

console.log(`Extracted ${businesses.length} businesses:`);
businesses.forEach((b, idx) => {
