const res = await browserjs(tabId, () => {
  const findInput = document.querySelector('input[name="find_text"]');
  const locInput = document.querySelector('input[name="find_loc"]');

  const setInputValue = (input, val) => {
    const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    nativeSetter.call(input, val);
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  };

  setInputValue(findInput, "roofing contractors");
  setInputValue(locInput, "10002");

  return {
    findVal: findInput.value,
    locVal: locInput.value
  };
});

console.log("Set values:", res);

