const tabId = 1148881640;

const results = await browserjs(tabId, () => {
  // Let's find all business result items
  // Usually BBB has result cards in div or article or li
  const searchResultsHeading = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.includes('Search results'));
  const container = searchResultsHeading ? searchResultsHeading.parentElement : document.body;

  // Find all cards
  // Let's look for headings level 3 or 4 inside search results
  const items = Array.from(container.querySelectorAll('div, li')).filter(el => {
    return el.querySelector('h3 a') && (el.textContent.includes('BBB Rating') || el.textContent.includes('Roofing'));
