const tabId = 1148881640;

const cardDetails = await browserjs(tabId, () => {
  // Find all h3 elements that contain links to business profiles
  const profileLinks = Array.from(document.querySelectorAll('a'))
    .filter(a => a.href && a.href.includes('/profile/'));

  // Let's get unique profile links
  const uniqueBusinesses = [];
  const seen = new Set();

  for (const a of profileLinks) {
    // Only look at the business name links (usually h3 > a)
    const h3 = a.closest('h3');
    if (!h3) continue;

    // Find the enclosing card container
    let container = h3;
    while (container && container.tagName !== 'MAIN') {
      if (container.classList && (container.className.includes('card') || container.className.includes('result') || container.className.includes('stack') || container.getAttribute('data-type') === 'search-result')) {
        // Check if this container has phone/address
        if (container.innerText.includes('BBB Rating') || container.innerText.includes('Roofing')) {
          break;
        }
      }
      container = container.parentElement;
    }
    if (!container || container.tagName === 'MAIN') {
      container = h3.parentElement;
    }

    const businessUrl = a.href;
    if (seen.has(businessUrl)) continue;
    seen.add(businessUrl);

    // Get text of container or parents up 3 levels
    let p = h3;
    let fullText = "";
    for (let i = 0; i < 4; i++) {
      if (p.parentElement && p.parentElement.tagName !== 'MAIN') {
        p = p.parentElement;
      }
    }
    fullText = p.innerText;

    uniqueBusinesses.push({
      name: h3.textContent.trim().replace(/^advertisement:\s*/i, ''),
      url: businessUrl,
      textSnippet: fullText
    });
  }

  return uniqueBusinesses;
});

console.log("Found businesses count:", cardDetails.length);
if (cardDetails.length > 0) {
  console.log("First card textSnippet:\n", cardDetails[0].textSnippet);
  console.log("Second card textSnippet:\n", cardDetails[1].textSnippet);
}

