      if (line.includes('Contractor') || line.includes('Roofing') || line.includes('Improvement') || line.includes('Services')) {
        if (!line.includes('advertisement') && !line.includes('Showing') && !line.includes('Department of Consumer') && !line.includes('BBB')) {
          categories.push(line);
        }
      }
    }

    if (!seen.has(name + (isAd ? '-ad' : ''))) {
      seen.add(name + (isAd ? '-ad' : ''));
      list.push({
        name,
        isAd,
        rating: ratingMatch ? ratingMatch[1] : 'N/A',
        isAccredited,
        phone: phoneMatch ? phoneMatch[0] : 'N/A',
        address: address || 'N/A',
        categories: categories.join('; '),
        url: cleanUrl
      });
    }
  }

  return list;
});

